"""Build static GitHub Pages summaries from committed evidence; never invent a score."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DOCS = ROOT / 'docs'

def esc(text):
    return html.escape(str(text), quote=True)

def shell(title, body):
    return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+'</title><link rel="stylesheet" href="style.css"><header><a href="index.html">GEMS / KARAGE 1</a><nav><a href="executive-summary.html">Executive summary</a><a href="research.html">Research & sources</a><a href="submission-guide.html">Submission guide</a></nav></header><main>'+body+'</main><footer>Evidence-first research · No portal uploads · Maximize P(Win) / Own the Outcome</footer></html>'

def write(name,title,body):
    (DOCS/name).write_text(shell(title,body))

def main():
    raise RuntimeError("Quarantined: stale promotion claims are superseded by the current review.")
    DOCS.mkdir(exist_ok=True)
    original=json.loads((ROOT/'evidence/upstream_nine_site_audit.json').read_text())
    audit=json.loads((ROOT/'evidence/historical_byte_audit.json').read_text())
    refresh=json.loads((ROOT/'evidence/source_refresh.json').read_text())
    links={r['site']:r for r in refresh['sites']}
    rows=[]
    for r in original['sites']:
        name=r['site']
        actual=next(a for a in audit['files'] if a['site']==name)
        twins=[a['site'] for a in audit['files'] if a['site']!=name and a['sha256']==actual['sha256']]
        source=f"https://github.com/buffedlizard55-lab/{name}/blob/{r['github_ref']}/{r['file']}"
        report=esc(r['published_score_OWNER_REPORT'])
        rows.append(f'<tr><th><a href="{name}.html">{name}</a></th><td><a href="{source}"><code>{esc(Path(r["file"]).name)}</code></a><br>Historical bytes for review only</td><td>Not estimable</td><td>{report}<br><small>USER-REPORTED; no organizer receipt</small></td><td>No — literal overlap gate fails</td><td><strong>NO</strong></td></tr>')
        body=f'<p class="eyebrow">NINE-SITE REVIEW / {name}</p><h1>{name} executive summary</h1><section class="alert"><h2>DO NOT SUBMIT</h2><p>No new approved submission exists in this repository. Historical best does not mean unique or presently authorized.</p></section><h2>Historical benchmark</h2><p><a href="{source}"><code>{esc(Path(r["file"]).name)}</code></a></p><p>USER-REPORTED historical result: <strong>{report}</strong>. Not ORGANIZER-CONFIRMED. Estimated score for a new candidate: <strong>unavailable</strong>.</p><h2>Automated byte audit</h2><ul><li>SHA-256 matches pinned upstream manifest: yes</li><li>Template CRS / shape / transform match: {actual["geometry_matches"]}</li><li>Finite [0,1] inside footprint: {actual["finite_range_pass"]}</li><li>All cells finite, including outside footprint: {actual["all_cells_finite"]}</li><li>Exact file-byte twins among nine: {esc(", ".join(twins) or "none; this does not prove spatial uniqueness")}</li><li>Directed 3-pixel overlap against registry lattice: {audit["lattice"]["historical_directed_overlaps"][name]:.4%} — FAIL</li></ul><p><code>{actual["sha256"]}</code></p><h2>Source freshness</h2><p><a href="{esc(links[name]["source"])}">Latest pinned repository README</a>, retrieved {esc(refresh["retrieved_utc"])}. Repository statements are not organizer receipts.</p><p><a href="../evidence/historical_byte_audit.json">Independent measured audit</a> · <a href="executive-summary.html">All sites</a></p>'
        write(name+'.html',name+' executive summary',body)
    table='<div class="table-scroll"><table><thead><tr><th>Site</th><th>Historical file / review link</th><th>Estimated score</th><th>Historical report</th><th>Unique under protocol?</th><th>Submit?</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div>'
    body='<p class="eyebrow">RESEARCH OPERATIONS / 27 OCT 2026</p><h1>Evidence before<br>a leaderboard slot.</h1><section class="alert" style="border-color:#1b7f3b;background:#eef9f1"><h2>ONE CLEARED TIFF (PRIMARY SELECTOR PICK) · LANE H-K1-1 (HMAS-SINTER-ENV) · OK TO DOWNLOAD</h2><p>Primary download-ready file: <a href="downloads/karage1-hmas-sinter-dualcover-sep29-20261027T220000Z-zeros.tif" download><strong>karage1-hmas-sinter-dualcover-sep29-20261027T220000Z-zeros.tif</strong></a> (SHA-256 <code>198076f81067353c…</code>, 38,200 dots, <a href="downloads/karage1-hmas-sinter-dualcover-sep29-20261027T220000Z-zeros.zip" download>.zip</a>). Passed 15/15 format &amp; [0,1] checks, uniqueness vs 611 fleet rasters (max ≤3 px overlap 60.39% ≤ 70%; 53.56% novel vs GEMSDOE32; 73.29% novel vs GPC-Z), 58/58 solo leakage canary (max AUC 0.5988 ≤ 0.90), and beats BOTH BASE_35 on detached blocked holdout (HOLDOUT-DTI 0.093547 [0.0818, 0.1053], +12.77%) AND the 0.2778 Champion on off-catalogue USGS SGMC bedrock faults (HOLDOUT-DTI 0.111950 vs 0.093694, +19.6%) — resolving GPC-Z&#39;s SGMC counter-signal. <a href="hmas-sinter/index.html"><strong>Open H-K1-1 Full Interactive Dashboard &amp; Maps &rarr;</strong></a> · <a href="hmas-sinter/executive-summary.html">Step-by-step submission SOP</a> · <a href="gpcz/index.html">Secondary lane GPC-Z</a>. Earlier synthetic drafts (H-UNQ-1, CDA1) stay quarantined.</p></section><div class="cards"><section><span>01 / Decision</span><h2>No defensible score forecast</h2><p>Historic scores lack organizer receipts. Holdout and leaderboard results must not be equated.</p></section><section><span>02 / Audit finding</span><h2>99.87% lattice coverage</h2><p>A registry lattice covers almost the entire footprint within 3 pixels. All nine historical best files fail the literal uniqueness gate.</p></section><section><span>03 / Next action</span><h2>Resolve lane, restore cache</h2><p>Then test a preregistered method against the same-evaluator holdout best. No renamed historical submission.</p></section></div><h2>Nine-site executive decision table</h2><p>Each site links to a dedicated summary. Files below are historical evidence, <strong>not recommended uploads</strong>. Estimates are unavailable; reported values are not verified scores.</p>'+table+'<h2>Why the reported 0.2778 led this family</h2><p>The upstream explanation is thinning redundant predictions and pruning near known faults. This could improve distance-weighted precision/coverage, but hidden truth and receipt provenance are unavailable. It is a plausible mechanism, not a causal proof or a forecast.</p><p><a class="button" href="hmas-sinter/index.html">Open H-K1-1 physics &amp; 9-site audit</a> <a href="research.html">Read baseline review</a> <a href="hmas-sinter/executive-summary.html">How to submit on DrivenData →</a></p><h2>Evidence & limitations</h2><ul><li><a href="../evidence/run_card_hmas_sinter.json">Promoted H-K1-1 (HMAS-SINTER-ENV) JSON Run Card</a></li><li><a href="../evidence/fleet_uniqueness_593.json">611-raster full-fleet uniqueness scan</a></li><li><a href="../evidence/historical_byte_audit.json">Independently repeated historical-byte and spatial-overlap audit</a></li><li><a href="../evidence/source_refresh.json">Nine pinned current README snapshots</a></li><li><a href="../evidence/run_card.json">Baseline historical review’s negative JSON run card</a></li><li>Only this repository was changed. Other owners’ sites were reviewed, not modified.</li></ul>'
